document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".faq-section .section-grid");document.querySelectorAll(".faq-section .grid-item .question").forEach(i=>{i.addEventListener("click",function(){var e=this.parentElement,t=(e.closest(".section-grid"),e.querySelector(".answer")),l=this.querySelector(".plus-icon"),s=this.querySelector(".minus-icon");"block"===t.style.display?(t.style.display="none",l.style.display="block",s.style.display="none",e.style.height="auto"):(t.style.display="block",l.style.display="none",s.style.display="block",l=i.offsetHeight,s=t.offsetHeight,e.style.height=l+s+40+"px")})})});